89	func (opaEval *OPAEvaluator) partiallyEvaluate(logger logging.Logger, input EvalInput, options *PolicyEvaluationOptions) (primitive.M, error) {
90		if options == nil {
91			options = &PolicyEvaluationOptions{}
92		}
93		opaEvaluationTimeStart := time.Now()
94	
95		if opaEval.evaluator.preparedPartialQuery == nil {
96			return nil, fmt.Errorf("%w: %s", ErrPartialPolicyEvalFailed, "preparedPartialQuery is nil")
97		}
98	
99		partialResults, err := opaEval.evaluator.preparedPartialQuery.Partial(
100			opaEval.getContext(),
101			rego.EvalParsedInput(input.Value),
102			rego.EvalPrintHook(NewPrintHook(os.Stdout, opaEval.PolicyName)),
103		)
104		if err != nil {
105			return nil, fmt.Errorf("%w: %s", ErrPartialPolicyEvalFailed, err.Error())
106		}
107	
108		opaEvaluationTime := time.Since(opaEvaluationTimeStart)
109	
110		options.metrics().PolicyEvaluationDurationMilliseconds.With(metrics.Labels{
111			"policy_name": opaEval.PolicyName,
112		}).Observe(float64(opaEvaluationTime.Milliseconds()))
113	
114		fields := map[string]any{
115			"evaluationTimeMicroseconds": opaEvaluationTime.Microseconds(),
116			"policyName":                 opaEval.PolicyName,
117			"partialEval":                true,
118			"allowed":                    true,
119		}
120		addDataToLogFields(fields, options.AdditionalLogFields)
121	
122		logger.WithFields(fields).Debug("policy evaluation completed")
123	
124		client := opatranslator.OPAClient{}
125		q, err := client.ProcessQuery(partialResults)
126		if err != nil {
127			return nil, err
128		}
129	
130		logger.WithFields(map[string]any{
131			"allowed": true,
132			"query":   q,
133		}).Trace("policy results and query")
134	
135		return q, nil
136	}
