138	func (opaEval *OPAEvaluator) Evaluate(logger logging.Logger, input EvalInput, options *PolicyEvaluationOptions) (interface{}, error) {
139		if options == nil {
140			options = &PolicyEvaluationOptions{}
141		}
142		if opaEval.evaluator.preparedEvalQuery == nil {
143			return nil, fmt.Errorf("%w: %s", ErrPolicyEvalFailed, "preparedEvalQuery is nil")
144		}
145	
146		opaEvaluationTimeStart := time.Now()
147	
148		results, err := opaEval.evaluator.preparedEvalQuery.Eval(
149			opaEval.getContext(),
150			rego.EvalParsedInput(input.Value),
151			rego.EvalPrintHook(NewPrintHook(os.Stdout, opaEval.PolicyName)),
152		)
153		if err != nil {
154			return nil, fmt.Errorf("%w: %s", ErrPolicyEvalFailed, err.Error())
155		}
156	
157		opaEvaluationTime := time.Since(opaEvaluationTimeStart)
158		options.metrics().PolicyEvaluationDurationMilliseconds.With(metrics.Labels{
159			"policy_name": opaEval.PolicyName,
160		}).Observe(float64(opaEvaluationTime.Milliseconds()))
161	
162		allowed, responseBodyOverwriter := processResults(results)
163		fields := map[string]any{
164			"evaluationTimeMicroseconds": opaEvaluationTime.Microseconds(),
165			"policyName":                 opaEval.PolicyName,
166			"partialEval":                false,
167			"allowed":                    allowed,
168			"resultsLength":              len(results),
169		}
170		addDataToLogFields(fields, options.AdditionalLogFields)
171	
172		logger.WithFields(fields).Debug("policy evaluation completed")
173	
174		logger.WithFields(map[string]any{
175			"policyName": opaEval.PolicyName,
176			"allowed":    allowed,
177		}).Info("policy result")
178	
179		if allowed {
180			return responseBodyOverwriter, nil
181		}
182		return nil, ErrPolicyNotAllowed
183	}
