185	func (evaluator *OPAEvaluator) getContext() context.Context {
186		ctx := evaluator.context
187		if ctx == nil {
188			ctx = context.Background()
189		}
190		if evaluator.mongoClient != nil {
191			ctx = custom_builtins.WithMongoClient(ctx, evaluator.mongoClient)
192		}
193		if evaluator.redisClient != nil {
194			// Check if redisClient implements the IRedisClient interface
195			if redisIface, ok := evaluator.redisClient.(custom_builtins.IRedisClient); ok {
196				ctx = custom_builtins.WithRedisClient(ctx, redisIface)
197			}
198		}
199		if evaluator.logger != nil {
200			ctx = logging.WithContext(ctx, evaluator.logger)
201		}
202		return ctx
203	}
