249	
250	func NewOPAModuleConfigWithBuiltins(modules []Module, builtinsDeclarations BuiltinDeclarations) (*OPAModuleConfig, error) {
251		builtins := map[string]*ast.Builtin{
252			custom_builtins.GetHeaderDecl.Name:              custom_builtins.GetHeaderDecl,
253			custom_builtins.MongoFindOneDecl.Name:           custom_builtins.MongoFindOneDecl,
254			custom_builtins.MongoFindManyDecl.Name:          custom_builtins.MongoFindManyDecl,
255			custom_builtins.RedisGetDecl.Name:               custom_builtins.RedisGetDecl,
256			custom_builtins.RedisSetDecl.Name:               custom_builtins.RedisSetDecl,
257			custom_builtins.RedisSetWithExpirationDecl.Name: custom_builtins.RedisSetWithExpirationDecl,
258			custom_builtins.RedisDelDecl.Name:               custom_builtins.RedisDelDecl,
259			audit.SetLabelsDecl.Name:                        audit.SetLabelsDecl,
260		}
261	
262		for name, decl := range builtinsDeclarations {
263			builtins[name] = decl
264		}
265	
266		compiler := ast.NewCompiler().WithBuiltins(builtins)
267	
268		modulesToCompile := map[string]*ast.Module{}
269		for _, m := range modules {
270			parsedModule := ast.MustParseModule(m.Content)
271			modulesToCompile[m.Name] = parsedModule
272		}
273		compiler.Compile(modulesToCompile)
274	
275		if compiler.Failed() {
276			return nil, fmt.Errorf("%w: %s", ErrModuleCompilationFailed, compiler.Errors)
277		}
278	
279		return &OPAModuleConfig{
280			Modules:  modules,
281			compiler: compiler,
282		}, nil
283	}
