315	func LoadRegoModule(rootDirectory string) (*OPAModuleConfig, error) {
316		var regoModulePath string
317		//#nosec G104 -- Produces a false positive
318		filepath.Walk(rootDirectory, func(path string, info os.FileInfo, err error) error {
319			if err != nil {
320				return err
321			}
322			if regoModulePath != "" {
323				return nil
324			}
325	
326			if filepath.Ext(path) == ".rego" {
327				regoModulePath = path
328			}
329			return nil
330		})
331	
332		if regoModulePath == "" {
333			return nil, ErrMissingRegoModules
334		}
335		fileContent, err := utils.ReadFile(regoModulePath)
336		if err != nil {
337			return nil, fmt.Errorf("%w: %s", ErrRegoModuleReadFailed, err.Error())
338		}
339	
340		return NewOPAModuleConfig([]Module{
341			{
342				Name:    filepath.Base(regoModulePath),
343				Content: string(fileContent),
344			},
345		})
346	}
347	
348	func processResults(results rego.ResultSet) (allowed bool, responseBodyOverwriter any) {
349		// Use strict allowed check for basic request flow allow policies.
350		if results.Allowed() {
351			allowed = true
352			return
353		}
354	
355		// Here extract first result set to get the response body for the response policy evaluation.
356		// The results returned by OPA are a list of Results object with fields:
357		// - Expressions: list of list
358		// - Bindings: object
359		// e.g. [{Expressions:[[map["element": true]]] Bindings:map[]}]
360		// Since we are ALWAYS querying ONE specific policy the result length could not be greater than 1
361		if len(results) == 1 {
362			if exprs := results[0].Expressions; len(exprs) == 1 {
363				if value, ok := exprs[0].Value.([]interface{}); ok && value != nil && len(value) != 0 {
364					allowed = true
365					responseBodyOverwriter = value[0]
366					return
367				}
368			}
369		}
370	
371		return
372	}
