28	const userAgentHeaderKey = "user-agent"
29	
30	type PolicyResult struct {
31		QueryToProxy []byte
32		Allowed      bool
33	}
34	
35	// Warning: This interface is experimental, and it could change with breaking also in rond patches.
36	// Do not use outside this repository until it is ready.
37	type Evaluator interface {
38		// retrieve the RondConfig used to generate the evaluator
39		Config() core.RondConfig
40	
41		// EvaluateResponsePolicy evaluate request policy. In the response, it is specified if the
42		// request is allowed and the request query (if filter generation is requested)
43		EvaluateRequestPolicy(ctx context.Context, input core.Input, options *EvaluateOptions) (PolicyResult, error)
44		// EvaluateResponsePolicy evaluate response policy. The response is the response
45		// value returned by the policy.
46		EvaluateResponsePolicy(ctx context.Context, input core.Input, options *EvaluateOptions) ([]byte, error)
47	}
48	
49	type evaluator struct {
50		rondConfig              core.RondConfig
51		opaModuleConfig         *core.OPAModuleConfig
52		partialResultEvaluators core.PartialResultsEvaluators
53	
54		evaluatorOptions        *EvaluatorOptions
55		policyEvaluationOptions *core.PolicyEvaluationOptions
56		auditAgentPool          audit.AgentPool
57	}
58	
59	func (e evaluator) Config() core.RondConfig {
60		return e.rondConfig
61	}
62	
63	type AuditOptions struct {
64		AggregationID string
65	}
66	
67	type EvaluateOptions struct {
68		Logger logging.Logger
69		Audit  AuditOptions
70	}
71	
72	func (e EvaluateOptions) GetLogger() logging.Logger {
73		if e.Logger == nil {
74			return logging.NewNoOpLogger()
75		}
76		return e.Logger
77	}
78	
79	func (e evaluator) EvaluateRequestPolicy(ctx context.Context, rondInput core.Input, options *EvaluateOptions) (PolicyResult, error) {
80		rondConfig := e.Config()
81		if options == nil {
82			options = &EvaluateOptions{}
83		}
84		logger := options.GetLogger()
85	
86		evalInput, err := core.CreateRegoQueryInput(logger, rondInput, core.RegoInputOptions{
87			EnableResourcePermissionsMapOptimization: rondConfig.Options.EnableResourcePermissionsMapOptimization,
88		})
89		if err != nil {
90			return PolicyResult{}, err
91		}
92	
93		opaEvaluatorOptions := e.evaluatorOptions.opaEvaluatorOptions(logger)
94	
95		auditAgent := e.auditAgentPool.New()
96		ctx = audit.WithAuditCache(ctx, auditAgent)
97		evaluatorAllowPolicy, err := e.partialResultEvaluators.GetEvaluatorFromPolicy(ctx, rondConfig.RequestFlow.PolicyName, opaEvaluatorOptions)
98		if err != nil {
99			return PolicyResult{}, err
100		}
101	
102		// TODO: here if the evaluation result false, it is returned an error. This interface
103		// for the sdk should be improved, since it should use the PolicyResult and return error
104		// only if there is some error in policy evaluation.
105		_, query, err := evaluatorAllowPolicy.PolicyEvaluation(logger, evalInput, e.policyEvaluationOptions)
106	
107		if err != nil {
108			logger.WithField("error", map[string]any{
109				"policyName": rondConfig.RequestFlow.PolicyName,
110				"message":    err.Error(),
111			}).Error("RBAC policy evaluation failed")
112	
113			if err := auditAgent.Trace(ctx, audit.Audit{
114				AggregationID: options.Audit.AggregationID,
115				Authorization: audit.AuthzInfo{
116					Allowed:    false,
117					PolicyName: rondConfig.RequestFlow.PolicyName,
118				},
119				Subject: audit.SubjectInfo{
120					ID:     rondInput.User.ID,
121					Groups: rondInput.User.Groups,
122				},
123				Request: audit.RequestInfo{
124					Verb:      rondInput.Request.Method,
125					Path:      rondInput.Request.Path,
126					UserAgent: rondInput.Request.Headers.Get(userAgentHeaderKey),
127				},
128				Timestamp: time.Now().UnixNano(),
129			}); err != nil {
130				logger.WithField("error", map[string]any{
131					"aggregationId": options.Audit.AggregationID,
132					"error":         map[string]any{"message": err.Error()},
133				}).Error("audit trace failed")
134			}
135	
136			if errors.Is(err, core.ErrPolicyNotAllowed) {
137				return PolicyResult{}, nil
138			}
139			return PolicyResult{}, err
140		}
141	
142		var queryToProxy []byte
143		if query != nil {
144			queryToProxy, err = json.Marshal(query)
145			if err != nil {
146				return PolicyResult{}, err
147			}
148		}
149	
150		if err := auditAgent.Trace(ctx, audit.Audit{
151			AggregationID: options.Audit.AggregationID,
152			Authorization: audit.AuthzInfo{
153				Allowed:    true,
154				PolicyName: rondConfig.RequestFlow.PolicyName,
155			},
156			Subject: audit.SubjectInfo{
157				ID:     rondInput.User.ID,
158				Groups: rondInput.User.Groups,
159			},
160			Request: audit.RequestInfo{
161				Verb:      rondInput.Request.Method,
162				Path:      rondInput.Request.Path,
163				UserAgent: rondInput.Request.Headers.Get(userAgentHeaderKey),
164			},
165			Timestamp: time.Now().UnixNano(),
166		}); err != nil {
167			logger.WithField("error", map[string]any{
168				"aggregationId": options.Audit.AggregationID,
169				"error":         map[string]any{"message": err.Error()},
170			}).Error("audit trace failed")
171		}
172	
173		return PolicyResult{
174			Allowed:      true,
175			QueryToProxy: queryToProxy,
176		}, nil
177	}
