179	func (e evaluator) EvaluateResponsePolicy(ctx context.Context, rondInput core.Input, options *EvaluateOptions) ([]byte, error) {
180		rondConfig := e.Config()
181		if options == nil {
182			options = &EvaluateOptions{}
183		}
184		logger := options.GetLogger()
185	
186		evalInput, err := core.CreateRegoQueryInput(logger, rondInput, core.RegoInputOptions{
187			EnableResourcePermissionsMapOptimization: rondConfig.Options.EnableResourcePermissionsMapOptimization,
188		})
189		if err != nil {
190			return nil, err
191		}
192	
193		opaEvaluatorOptions := e.evaluatorOptions.opaEvaluatorOptions(logger)
194	
195		auditAgent := e.auditAgentPool.New()
196		ctx = audit.WithAuditCache(ctx, auditAgent)
197		evaluator, err := e.partialResultEvaluators.GetEvaluatorFromPolicy(ctx, e.rondConfig.ResponseFlow.PolicyName, opaEvaluatorOptions)
198		if err != nil {
199			return nil, err
200		}
201	
